create table if not exists public.competitor_signal_history (id uuid primary key default gen_random_uuid(), workspace_id uuid not null, business_id uuid, competitor_id uuid, source_type text not null, source_uri text, observed_at timestamptz not null default now(), signal_type text not null, signal_data jsonb not null default '{}'::jsonb, evidence_id uuid references public.business_intelligence_evidence(id) on delete set null, created_at timestamptz not null default now()); create index if not exists idx_comp_signal_workspace_observed on public.competitor_signal_history(workspace_id, observed_at desc); alter table public.competitor_signal_history enable row level security; create policy "members_read_competitor_signal_history" on public.competitor_signal_history for select to authenticated using (public.is_workspace_member(auth.uid(), workspace_id));;
